with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__DISC_CASE_ID))) as HUB_CLAIM_HK
        , 'DISCOUNT' as BILL_LINE_TYPE
        , coalesce(nullif(trim(DISC_PARTICULAR_RAW), ''), '') as LINE_PARTICULAR
        , cast(null as varchar) as BILL_HEAD_CODE
        , DISC_AMOUNT as LINE_AMOUNT
        , DISC_PARTICULAR_LEAD_TERM as LINE_PARTICULAR_LEAD_TERM
        , DISC_PARTICULAR_PROFILE_TERM as LINE_PARTICULAR_PROFILE_TERM
        , cast(null as varchar) as LINE_AMOUNT_PER_UNIT
        , cast(null as varchar) as LINE_CLAIMED_AMOUNT
        , cast(null as varchar) as LINE_UNIT_COUNT
        , cast(null as varchar) as LINE_PAYABLE_INDICATOR
        , cast(null as varchar) as BILL_HEAD_LEVEL_1_NAME
        , cast(null as varchar) as BILL_HEAD_LEVEL_2_NAME
        , cast(null as varchar) as BILL_HEAD_LEVEL_3_NAME
        , cast(null as varchar) as LINE_SEQUENCE_NUMBER
        , 'BJAZ_HAT_DISC_SUMMARY_LST' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_disc_summary_lst') }}
    where (nullif(trim(DISC_CASE_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__NON_PAY_CASE_ID))) as HUB_CLAIM_HK
        , 'NON_PAYABLE' as BILL_LINE_TYPE
        , coalesce(nullif(trim(NON_PAY_PARTICULAR), ''), '') as LINE_PARTICULAR
        , coalesce(nullif(trim(BILLHEAD), ''), '') as BILL_HEAD_CODE
        , cast(null as varchar) as LINE_AMOUNT
        , cast(null as varchar) as LINE_PARTICULAR_LEAD_TERM
        , cast(null as varchar) as LINE_PARTICULAR_PROFILE_TERM
        , NON_PAY_AMT_PERUNIT as LINE_AMOUNT_PER_UNIT
        , NON_PAY_CLAIMED_AMOUNT as LINE_CLAIMED_AMOUNT
        , NON_PAY_UNIT as LINE_UNIT_COUNT
        , NON_PAY_IS_PAYABLE as LINE_PAYABLE_INDICATOR
        , NON_PAY_LEVEL_1 as BILL_HEAD_LEVEL_1_NAME
        , NON_PAY_LEVEL_2 as BILL_HEAD_LEVEL_2_NAME
        , NON_PAY_LEVEL_3 as BILL_HEAD_LEVEL_3_NAME
        , cast(null as varchar) as LINE_SEQUENCE_NUMBER
        , 'BJAZ_HAT_NON_PAYABLE_LST' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_non_payable_lst') }}
    where (nullif(trim(NON_PAY_CASE_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__RET_CASE_ID))) as HUB_CLAIM_HK
        , 'RETURNED' as BILL_LINE_TYPE
        , coalesce(nullif(trim(RET_PARTICULAR), ''), '') as LINE_PARTICULAR
        , cast(null as varchar) as BILL_HEAD_CODE
        , cast(null as varchar) as LINE_AMOUNT
        , cast(null as varchar) as LINE_PARTICULAR_LEAD_TERM
        , cast(null as varchar) as LINE_PARTICULAR_PROFILE_TERM
        , RET_AMOUNT_PER_UNIT as LINE_AMOUNT_PER_UNIT
        , RET_CLAIMED_AMOUNT as LINE_CLAIMED_AMOUNT
        , RET_UNIT as LINE_UNIT_COUNT
        , RET_IS_PAYABLE as LINE_PAYABLE_INDICATOR
        , RET_LEVEL_1 as BILL_HEAD_LEVEL_1_NAME
        , RET_LEVEL_2 as BILL_HEAD_LEVEL_2_NAME
        , RET_LEVEL_3 as BILL_HEAD_LEVEL_3_NAME
        , cast(null as varchar) as LINE_SEQUENCE_NUMBER
        , 'BJAZ_HAT_RETURN_SUMMARY_LST' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_return_summary_lst') }}
    where (nullif(trim(RET_CASE_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CASE_ID))) as HUB_CLAIM_HK
        , 'OCR_PARTICULAR' as BILL_LINE_TYPE
        , coalesce(nullif(trim(PARTICULAR), ''), '') as LINE_PARTICULAR
        , coalesce(nullif(trim(BILLHEAD), ''), '') as BILL_HEAD_CODE
        , AMOUNT as LINE_AMOUNT
        , cast(null as varchar) as LINE_PARTICULAR_LEAD_TERM
        , cast(null as varchar) as LINE_PARTICULAR_PROFILE_TERM
        , cast(null as varchar) as LINE_AMOUNT_PER_UNIT
        , cast(null as varchar) as LINE_CLAIMED_AMOUNT
        , cast(null as varchar) as LINE_UNIT_COUNT
        , cast(null as varchar) as LINE_PAYABLE_INDICATOR
        , cast(null as varchar) as BILL_HEAD_LEVEL_1_NAME
        , cast(null as varchar) as BILL_HEAD_LEVEL_2_NAME
        , LEVEL_3 as BILL_HEAD_LEVEL_3_NAME
        , SR_NO as LINE_SEQUENCE_NUMBER
        , 'BJAZ_HAT_OCR_FINA_PERTICULARS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_ocr_fina_perticulars') }}
    where (nullif(trim(CASE_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        BILL_LINE_TYPE,
        LINE_PARTICULAR,
        BILL_HEAD_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then LINE_AMOUNT end) as LINE_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then LINE_PARTICULAR_LEAD_TERM end) as LINE_PARTICULAR_LEAD_TERM,
        max(case when SOURCE_RUN = 'opus_health_v2' then LINE_PARTICULAR_PROFILE_TERM end) as LINE_PARTICULAR_PROFILE_TERM,
        max(case when SOURCE_RUN = 'opus_health_v2' then LINE_AMOUNT_PER_UNIT end) as LINE_AMOUNT_PER_UNIT,
        max(case when SOURCE_RUN = 'opus_health_v2' then LINE_CLAIMED_AMOUNT end) as LINE_CLAIMED_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then LINE_UNIT_COUNT end) as LINE_UNIT_COUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then LINE_PAYABLE_INDICATOR end) as LINE_PAYABLE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then BILL_HEAD_LEVEL_1_NAME end) as BILL_HEAD_LEVEL_1_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then BILL_HEAD_LEVEL_2_NAME end) as BILL_HEAD_LEVEL_2_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then BILL_HEAD_LEVEL_3_NAME end) as BILL_HEAD_LEVEL_3_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then LINE_SEQUENCE_NUMBER end) as LINE_SEQUENCE_NUMBER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK, BILL_LINE_TYPE, LINE_PARTICULAR, BILL_HEAD_CODE
),

hashed as (
    select
        *,
        case when BILL_LINE_TYPE is not null or LINE_PARTICULAR is not null or BILL_HEAD_CODE is not null or LINE_AMOUNT is not null or LINE_PARTICULAR_LEAD_TERM is not null or LINE_PARTICULAR_PROFILE_TERM is not null or LINE_AMOUNT_PER_UNIT is not null or LINE_CLAIMED_AMOUNT is not null or LINE_UNIT_COUNT is not null or LINE_PAYABLE_INDICATOR is not null or BILL_HEAD_LEVEL_1_NAME is not null or BILL_HEAD_LEVEL_2_NAME is not null or BILL_HEAD_LEVEL_3_NAME is not null or LINE_SEQUENCE_NUMBER is not null
                     then md5(upper(coalesce(cast(BILL_LINE_TYPE as varchar), '') || '|' || coalesce(cast(LINE_PARTICULAR as varchar), '') || '|' || coalesce(cast(BILL_HEAD_CODE as varchar), '') || '|' || coalesce(cast(LINE_AMOUNT as varchar), '') || '|' || coalesce(cast(LINE_PARTICULAR_LEAD_TERM as varchar), '') || '|' || coalesce(cast(LINE_PARTICULAR_PROFILE_TERM as varchar), '') || '|' || coalesce(cast(LINE_AMOUNT_PER_UNIT as varchar), '') || '|' || coalesce(cast(LINE_CLAIMED_AMOUNT as varchar), '') || '|' || coalesce(cast(LINE_UNIT_COUNT as varchar), '') || '|' || coalesce(cast(LINE_PAYABLE_INDICATOR as varchar), '') || '|' || coalesce(cast(BILL_HEAD_LEVEL_1_NAME as varchar), '') || '|' || coalesce(cast(BILL_HEAD_LEVEL_2_NAME as varchar), '') || '|' || coalesce(cast(BILL_HEAD_LEVEL_3_NAME as varchar), '') || '|' || coalesce(cast(LINE_SEQUENCE_NUMBER as varchar), '')))
                end as SAT_CLAIM_BILL_LINE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_BILL_LINE_HASHDIFF is not null
